INSERT INTO cotizaciones (numero_cotizacion, proyecto_id, cliente_id, fecha, estado) SELECT '2026-819-AN', p.id, c.id, '2026-09-11', 'aprobada' FROM clientes c JOIN proyectos p ON p.cliente_id = c.id AND p.nombre = 'CASA OLOFSONN ADICIONAL' WHERE c.nombre = 'NEW AGE CONSTRUCTION' AND NOT EXISTS (SELECT 1 FROM cotizaciones WHERE numero_cotizacion = '2026-819-AN');
INSERT INTO ops (numero_op, cotizacion_id, proyecto_id, cliente_id, fecha_emision, fecha_pactada, oc_cliente, observaciones_comercial, estado_general) SELECT '2026-275', (SELECT id FROM cotizaciones WHERE numero_cotizacion = '2026-819-AN'), p.id, c.id, '2026-09-11', NULL, NULL, NULL, 'abierta' FROM clientes c JOIN proyectos p ON p.cliente_id = c.id AND p.nombre = 'CASA OLOFSONN ADICIONAL' WHERE c.nombre = 'NEW AGE CONSTRUCTION' AND NOT EXISTS (SELECT 1 FROM ops WHERE numero_op = '2026-275');
